INSERT INTO changelog (title, body, created_at) VALUES
('Джері кладе файли на Google Диск',
'Новий інструмент drive_save_files: Джері зберігає в папку клієнта на Диску фото і файли з Telegram-групи (конкретні або N останніх) і креативи Meta-реклами (карусель — усі картки, відео — обкладинка). За замовчуванням — у «Креативи», можна іншу підпапку (дані, портфоліо, документи, сайт) і свою вкладену, напр. «Листопад». Просто скажи: «закинь останні 3 креативи з групи на Диск у креативи, папка Листопад». Тумблер — «Google Диск» у «Можливостях». Обмеження: писати можна тільки в папки, які створила система (так налаштований доступ Google); файли понад 20 МБ з Telegram бот не скачає.',
'2026-11-01 12:00:00');
